-- The schema of a fresh install at SCHEMA_VERSION 5. Do not edit by hand: regenerate with
-- python tools/pin_schema.py (see the schema versions checklist in app.py).
index audit_hh: CREATE INDEX audit_hh ON audit(household_id, at)
index audit_sid: CREATE INDEX audit_sid ON audit(session_id)
index bill_snapshots_sid: CREATE INDEX bill_snapshots_sid ON bill_snapshots(session_id)
index documents_sid: CREATE INDEX documents_sid ON documents(session_id)
index expenses_sid: CREATE INDEX expenses_sid ON expenses(session_id)
index lines_sid: CREATE INDEX lines_sid ON lines(session_id)
index log_hh: CREATE INDEX log_hh ON log(household_id, at)
index log_sid: CREATE INDEX log_sid ON log(session_id)
index payments_sid: CREATE INDEX payments_sid ON payments(session_id)
index people_hh: CREATE INDEX people_hh ON people(household_id)
index photo_files_name: CREATE UNIQUE INDEX photo_files_name ON photo_files(session_id, kind, name)
index photo_files_sid: CREATE INDEX photo_files_sid ON photo_files(session_id, kind)
index sessions_event: CREATE INDEX sessions_event ON sessions(event_id)
index sessions_hh: CREATE INDEX sessions_hh ON sessions(household_id)
index sessions_stage: CREATE INDEX sessions_stage ON sessions(stage)
index stage_log_sid: CREATE INDEX stage_log_sid ON stage_log(session_id)
index step_closes_sid: CREATE INDEX step_closes_sid ON step_closes(session_id)
index tasks_eid: CREATE INDEX tasks_eid ON tasks(event_id)
index tasks_sid: CREATE INDEX tasks_sid ON tasks(session_id)
table audit: CREATE TABLE audit ( id INTEGER PRIMARY KEY, at TEXT NOT NULL, household_id INTEGER, session_id INTEGER, event_id INTEGER, action TEXT NOT NULL, note TEXT DEFAULT '', who TEXT DEFAULT 'Owner', route TEXT DEFAULT '', data TEXT DEFAULT '')
table bill_snapshots: CREATE TABLE bill_snapshots (number TEXT PRIMARY KEY, session_id INTEGER REFERENCES sessions(id) ON DELETE CASCADE, kind TEXT NOT NULL, at TEXT, sig TEXT, data TEXT NOT NULL, html TEXT)
table books: CREATE TABLE books ( id INTEGER PRIMARY KEY, received TEXT, amount REAL, tax REAL DEFAULT 0, type TEXT, kind TEXT)
table doc_numbers: CREATE TABLE doc_numbers (session_id INTEGER REFERENCES sessions(id) ON DELETE CASCADE, kind TEXT NOT NULL, number TEXT NOT NULL UNIQUE, issued TEXT, PRIMARY KEY (session_id, kind))
table doc_snapshots: CREATE TABLE doc_snapshots ( kind TEXT NOT NULL, ref INTEGER NOT NULL, at TEXT, data TEXT NOT NULL, PRIMARY KEY (kind, ref))
table doc_snapshots_old: CREATE TABLE doc_snapshots_old ( kind TEXT NOT NULL, ref INTEGER NOT NULL, at TEXT, data TEXT NOT NULL, moved TEXT)
table documents: CREATE TABLE documents ( id INTEGER PRIMARY KEY, session_id INTEGER REFERENCES sessions(id) ON DELETE CASCADE, kind TEXT NOT NULL, about_person INTEGER REFERENCES people(id) ON DELETE SET NULL, signer TEXT DEFAULT '', status TEXT DEFAULT 'needed', sent TEXT, signed TEXT, note TEXT DEFAULT '')
table events: CREATE TABLE events ( id INTEGER PRIMARY KEY, name TEXT NOT NULL, date TEXT, venue TEXT DEFAULT '', notes TEXT DEFAULT '', demo INTEGER DEFAULT 0, "billing" TEXT DEFAULT 'free', "rights" TEXT DEFAULT 'families', "rights_note" TEXT DEFAULT '', "payer_hid" INTEGER, "contact_hid" INTEGER, "family_price" REAL)
table expenses: CREATE TABLE expenses ( id INTEGER PRIMARY KEY, session_id INTEGER REFERENCES sessions(id) ON DELETE CASCADE, date TEXT, label TEXT NOT NULL, amount REAL DEFAULT 0, miles REAL DEFAULT 0, "rate" REAL)
table fee_schedules: CREATE TABLE fee_schedules (id INTEGER PRIMARY KEY AUTOINCREMENT, created TEXT, items TEXT NOT NULL, note TEXT DEFAULT '')
table galleries: CREATE TABLE galleries ( session_id INTEGER PRIMARY KEY REFERENCES sessions(id) ON DELETE CASCADE, source_dir TEXT DEFAULT '', built_at TEXT, n_files INTEGER DEFAULT 0, out_dir TEXT DEFAULT '', key TEXT NOT NULL, "picks_hash" TEXT DEFAULT '', "limits_days" INTEGER, "ekey" TEXT DEFAULT '', "draft_n" INTEGER, "draft_at" TEXT, "proof" INTEGER DEFAULT 0, "prune_due" TEXT, "cw_fixed" TEXT, "upload_state" TEXT DEFAULT '', "uploaded_at" TEXT, "removed_at" TEXT, "upload_error" TEXT DEFAULT '')
table households: CREATE TABLE households ( id INTEGER PRIMARY KEY, name TEXT NOT NULL, address TEXT DEFAULT '', source TEXT DEFAULT '', referred_by INTEGER REFERENCES households(id), notes TEXT DEFAULT '', demo INTEGER DEFAULT 0, created TEXT DEFAULT CURRENT_TIMESTAMP, "company" TEXT DEFAULT '')
table id_marks: CREATE TABLE id_marks (name TEXT PRIMARY KEY, n INTEGER NOT NULL)
table invoice_sent: CREATE TABLE invoice_sent (session_id INTEGER PRIMARY KEY REFERENCES sessions(id) ON DELETE CASCADE, number TEXT NOT NULL, sig TEXT NOT NULL)
table letters_printed: CREATE TABLE letters_printed ( session_id INTEGER PRIMARY KEY REFERENCES sessions(id) ON DELETE CASCADE, at TEXT NOT NULL)
table lines: CREATE TABLE lines ( id INTEGER PRIMARY KEY, session_id INTEGER REFERENCES sessions(id) ON DELETE CASCADE, label TEXT NOT NULL, amount REAL NOT NULL DEFAULT 0, "kind" TEXT DEFAULT 'custom', "fee_key" TEXT DEFAULT '', "qty" REAL DEFAULT 1, "unit" REAL, "taxable" INTEGER DEFAULT 1)
table log: CREATE TABLE log ( id INTEGER PRIMARY KEY, household_id INTEGER REFERENCES households(id) ON DELETE CASCADE, session_id INTEGER REFERENCES sessions(id) ON DELETE SET NULL, at TEXT DEFAULT CURRENT_TIMESTAMP, channel TEXT DEFAULT 'note', summary TEXT NOT NULL, written_at TEXT)
table payments: CREATE TABLE payments ( id INTEGER PRIMARY KEY, session_id INTEGER REFERENCES sessions(id) ON DELETE CASCADE, kind TEXT DEFAULT 'deposit', amount REAL NOT NULL, received TEXT, method TEXT DEFAULT '', "voided" TEXT, "ref" TEXT DEFAULT '')
table people: CREATE TABLE people ( id INTEGER PRIMARY KEY, household_id INTEGER NOT NULL REFERENCES households(id) ON DELETE CASCADE, name TEXT NOT NULL, role TEXT DEFAULT 'adult', is_minor INTEGER DEFAULT 0, grad_year INTEGER, email TEXT DEFAULT '', phone TEXT DEFAULT '', notes TEXT DEFAULT '', "relation" TEXT DEFAULT '', "gender" TEXT DEFAULT '', "birth_year" INTEGER, "birth_date" TEXT, "age_approx" INTEGER DEFAULT 0)
table photo_deleted: CREATE TABLE photo_deleted (id TEXT PRIMARY KEY)
table photo_files: CREATE TABLE photo_files ( id TEXT PRIMARY KEY, session_id INTEGER REFERENCES sessions(id) ON DELETE CASCADE, kind TEXT NOT NULL, name TEXT NOT NULL, size INTEGER NOT NULL, received INTEGER DEFAULT 0, ct_len INTEGER DEFAULT 0, records INTEGER DEFAULT 0, fkey TEXT NOT NULL, state TEXT DEFAULT 'partial', created TEXT DEFAULT CURRENT_TIMESTAMP, done_at TEXT, mirrored TEXT, "key_trail" TEXT DEFAULT '[]')
table photo_orphans: CREATE TABLE photo_orphans (id TEXT PRIMARY KEY, first_seen TEXT NOT NULL)
table quote_marks: CREATE TABLE quote_marks (vid INTEGER PRIMARY KEY REFERENCES quote_versions(id) ON DELETE CASCADE, session_id INTEGER, at TEXT NOT NULL)
table quote_versions: CREATE TABLE quote_versions (id INTEGER PRIMARY KEY, session_id INTEGER REFERENCES sessions(id) ON DELETE CASCADE, at TEXT, schedule_id INTEGER, expires TEXT, data TEXT NOT NULL)
table quotes: CREATE TABLE quotes (session_id INTEGER PRIMARY KEY REFERENCES sessions(id) ON DELETE CASCADE, schedule_id INTEGER REFERENCES fee_schedules(id), discount_pct REAL DEFAULT 0, discount_reason TEXT DEFAULT '', created TEXT, expires TEXT, "sent" TEXT)
table refund_credits: CREATE TABLE refund_credits (payment_id INTEGER PRIMARY KEY REFERENCES payments(id) ON DELETE CASCADE, session_id INTEGER, amount REAL NOT NULL)
table retention: CREATE TABLE retention ( session_id INTEGER PRIMARY KEY REFERENCES sessions(id) ON DELETE CASCADE, raw_dir TEXT DEFAULT '', keep_until TEXT, purged_at TEXT, "early_note" TEXT DEFAULT '', "sealed_at" TEXT, "unsealed_dir" TEXT DEFAULT '', "unsealed_at" TEXT, "notice" TEXT DEFAULT '{}', "keep_days" INTEGER)
table session_people: CREATE TABLE session_people ( session_id INTEGER REFERENCES sessions(id) ON DELETE CASCADE, person_id INTEGER REFERENCES people(id) ON DELETE CASCADE, PRIMARY KEY (session_id, person_id))
table sessions: CREATE TABLE sessions ( id INTEGER PRIMARY KEY, household_id INTEGER NOT NULL REFERENCES households(id) ON DELETE CASCADE, event_id INTEGER REFERENCES events(id) ON DELETE SET NULL, type TEXT NOT NULL, stage TEXT NOT NULL DEFAULT 'inquiry', title TEXT DEFAULT '', shoot_date TEXT, start_time TEXT DEFAULT '', stops TEXT DEFAULT '', intake TEXT DEFAULT '{}', notes TEXT DEFAULT '', gallery_id TEXT DEFAULT '', gallery_built TEXT, letter_mailed TEXT, first_visit TEXT, extension_used INTEGER DEFAULT 0, sd_shipped TEXT, favorites TEXT DEFAULT '', veto TEXT DEFAULT '', created TEXT DEFAULT CURRENT_TIMESTAMP, stage_changed TEXT DEFAULT CURRENT_TIMESTAMP, "duration_min" INTEGER, "lost_reason" TEXT DEFAULT '', "hold_stage" TEXT, "portfolio_no" INTEGER DEFAULT 0, "delivery_method" TEXT, "gallery_codeword" TEXT DEFAULT '', "tax_exempt" INTEGER DEFAULT 0, "tax_area" TEXT, "retouch_picks" TEXT DEFAULT '', "payer_event" INTEGER, "date_tentative" INTEGER DEFAULT 0, "plan_of" INTEGER, "po_number" TEXT DEFAULT '', "lic_term" TEXT DEFAULT '', "lic_territory" TEXT DEFAULT '', "lic_exclusive" INTEGER DEFAULT 0, "priced_on" TEXT, "tax_rate" REAL)
table settings: CREATE TABLE settings (key TEXT PRIMARY KEY, value TEXT)
table side_keys: CREATE TABLE side_keys (name TEXT PRIMARY KEY, key TEXT NOT NULL)
table sqlite_sequence: CREATE TABLE sqlite_sequence(name,seq)
table stage_log: CREATE TABLE stage_log ( id INTEGER PRIMARY KEY, session_id INTEGER REFERENCES sessions(id) ON DELETE CASCADE, stage TEXT NOT NULL, at TEXT DEFAULT (date('now','localtime')))
table step_closes: CREATE TABLE step_closes ( session_id INTEGER REFERENCES sessions(id) ON DELETE CASCADE, step TEXT NOT NULL, outcome TEXT NOT NULL, at TEXT DEFAULT (date('now','localtime')), note TEXT DEFAULT '', PRIMARY KEY (session_id, step))
table tasks: CREATE TABLE tasks ( id INTEGER PRIMARY KEY, session_id INTEGER REFERENCES sessions(id) ON DELETE CASCADE, title TEXT NOT NULL, offset_days INTEGER, due TEXT, done TEXT, sort INTEGER DEFAULT 0, stage TEXT, own INTEGER DEFAULT 0, event_id INTEGER REFERENCES events(id) ON DELETE CASCADE, outcome TEXT, outcome_note TEXT)
table users: CREATE TABLE users (id INTEGER PRIMARY KEY, name TEXT NOT NULL, email TEXT NOT NULL UNIQUE, pw_hash TEXT NOT NULL DEFAULT '', totp_secret TEXT NOT NULL, recovery TEXT NOT NULL DEFAULT '[]', created TEXT, failed INTEGER DEFAULT 0, locked_until TEXT, "totp_last" INTEGER DEFAULT 0)
table vault_keys: CREATE TABLE vault_keys (session_id INTEGER PRIMARY KEY, pub TEXT NOT NULL, wrapped TEXT NOT NULL, created TEXT, orphaned TEXT)
table vault_objects: CREATE TABLE vault_objects (id INTEGER PRIMARY KEY, session_id INTEGER, kind TEXT NOT NULL, name TEXT NOT NULL, backend TEXT NOT NULL, size INTEGER, sha256 TEXT, created TEXT, deleted TEXT)
table vault_secondary: CREATE TABLE vault_secondary (name TEXT PRIMARY KEY, size INTEGER, sha256 TEXT, copied TEXT)
